def ratio(v,t):
    if v == "": return ""
    return (Decimal(v)/Decimal(t)).quantize(Decimal("0.00000001"),rounding=ROUND_HALF_UP)

def page(v):
    return str(int(v)) if isinstance(v,float) and v.is_integer() else str(v)

def main():
    d=pd.read_csv(WORKTABLE,dtype={"股票代码":str})
    d=d[(d.年份==2023)&d.股票代码.isin([r["c"] for r in R])].set_index("股票代码")
    assert len(R)==45 and len(d)==45 and len({r['c'] for r in R})==45
    rows=[]
    for r in R:
        x=d.loc[r['c']]; sr,er=ratio(r['s'],r['t']),ratio(r['e'],r['t'])
        if r['sc'] in {'是','否'}: assert (sr>=Decimal('.5'))==(r['sc']=='是')
        if er!='' and r['ec'] in {'是','否'}: assert (er>=Decimal('.5'))==(r['ec']=='是')
        if er!='' and r['bc'] in {'是','否'}: assert (Decimal('.3')<=er<Decimal('.5'))==(r['bc']=='是')
        eligibility=('是（严格样本）' if r['sc']=='是' else '是（扩展样本）' if r['ec']=='是' else '否（仅边界稳健性）' if r['bc']=='是' else '待核实' if '待核实' in {r['sc'],r['ec'],r['bc']} else '否（低于30%或不属于扩展范围）')
        rows.append({'股票代码':r['c'],'公司全称':x['公司全称'],'年份':2023,'公司营业收入_元':r['t'],'严格口径涉农业务':r['sn'],'严格口径涉农收入_元':r['s'],'严格口径涉农收入占比':f'{sr:.8f}','扩展口径涉农业务':r['en'],'扩展口径涉农收入_元':r['e'],'扩展口径涉农收入占比':'' if er=='' else f'{er:.8f}','是否存在分部收入重叠':r.get('ov','否（同一披露维度；不符合范围的业务未计入）'),'严格样本结论':r['sc'],'扩展样本结论':r['ec'],'边界样本结论':r['bc'],'当年曾ST_已核实':'是' if x['当年曾ST_已核实']=='是' else '否','最终回归样本资格_当前规则':eligibility,'纳入或剔除理由':r['why'],'主营业务证据PDF页序号':page(x['年报主营业务表PDF页序号']),'营业收入证据PDF页序号':page(x['利润表PDF页序号']),'年报链接':x['年报链接'],'复核状态':'已人工复核（龙头独有剩余45家）','复核日期':'2026-08-10'})
    out=pd.DataFrame(rows); assert not out.duplicated(['股票代码','年份']).any()
    out.to_csv(OUTPUT,index=False,encoding='utf-8-sig')
    print(out.groupby(['扩展样本结论','边界样本结论']).size())

if __name__=='__main__': main()
